# Generated by build.py from recipe.yml for recipe smtp-require-starttls. Do not edit.
set -e
cd "$(dirname "$0")"
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
surl --cert server.pem --key server.key --user alice:s3cret smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ pop3://127.0.0.1:8082/ smtps://127.0.0.1:8083/ imaps://127.0.0.1:8084/ pop3s://127.0.0.1:8085/ &
sleep 1
curl --ssl-reqd --cacert server.pem -u alice:s3cret --crlf --mail-from ann@example.com --mail-rcpt alice@example.com -T lunch.txt smtp://127.0.0.1:8080/example.com --next --ssl-reqd --cacert server.pem -u alice:s3cret "imap://127.0.0.1:8081/INBOX;UID=1;SECTION=TEXT"
kill $(jobs -p)
